describe('beforeSession failure cleanup', () => {
  it('runs lifecycle failure hooks and preserves the original rejection', async () => {
    const failure = new Error('setup failed');
    const callOrder: string[] = [];
    const orchestrator = createChatOrchestrator(createMockProvider('unused'), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw failure;
        },
        onError: async (_session, error) => {
          callOrder.push(error === failure ? 'onError' : 'wrongError');
        },
        afterSession: async () => {
          callOrder.push('afterSession');
        },
      },
    });

    const rejection = await outcomeOf(orchestrator.processMessage(createSession('hello')));

    expect({rejection, callOrder}).toEqual({
      rejection: 'setup failed',
      callOrder: ['onError', 'afterSession'],
    });
  });
});
EOF
